import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Developer Monthly | 2025-04-02 | Part 1","description":"","frontmatter":{"title":"Ceph Developer Monthly | 2025-04-02 | Part 1","date":"2025-04-02T00:00:00.000Z","updated":"2025-04-03T00:00:00.000Z","tags":["Ceph","测试优化","Jenkins CI","分布式存储","开发流程"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Developer_Monthly_2025-04-02_Part_1.md","filePath":"posts/2025/Ceph_Developer_Monthly_2025-04-02_Part_1.md","lastUpdated":1780459816000}'),n={name:"posts/2025/Ceph_Developer_Monthly_2025-04-02_Part_1.md"};function l(s,e,i,h,c,g){return t(),a("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要-ceph-pr检查改进讨论" tabindex="-1">会议纪要：Ceph PR检查改进讨论 <a class="header-anchor" href="#会议纪要-ceph-pr检查改进讨论" aria-label="Permalink to &quot;会议纪要：Ceph PR检查改进讨论&quot;">​</a></h3><p><strong>会议时间</strong>：2023年<br><strong>参会人员</strong>：Casey、Ilia、Yva、Joseph、Adam等</p><h4 id="会议议题" tabindex="-1">会议议题： <a class="header-anchor" href="#会议议题" aria-label="Permalink to &quot;会议议题：&quot;">​</a></h4><ol><li><strong>改进<code>make check</code>的可靠性和减少运行时间</strong></li><li><strong>讨论Jenkins CI系统的优化</strong></li></ol><h3 id="讨论内容" tabindex="-1">讨论内容： <a class="header-anchor" href="#讨论内容" aria-label="Permalink to &quot;讨论内容：&quot;">​</a></h3><h4 id="_1-make-check的现状与问题" tabindex="-1">1. <strong><code>make check</code>的现状与问题</strong> <a class="header-anchor" href="#_1-make-check的现状与问题" aria-label="Permalink to &quot;1. **`make check`的现状与问题**&quot;">​</a></h4><ul><li><strong>现状</strong>：<code>make check</code>复杂度随时间增加，运行时间长，可靠性下降，Jenkins上频繁失败。</li><li><strong>问题</strong>：测试失败率高，运行时间过长，Jenkins服务器负载高，影响开发者效率。</li></ul><h4 id="_2-改进建议" tabindex="-1">2. <strong>改进建议</strong> <a class="header-anchor" href="#_2-改进建议" aria-label="Permalink to &quot;2. **改进建议**&quot;">​</a></h4><ul><li><strong>移除长时测试</strong>：将长时测试从<code>make check</code>中移出，只在Toothology中运行。</li><li><strong>按需触发测试</strong>：仅在PR准备好合并时手动触发全量测试。</li><li><strong>按组件拆分测试</strong>：按组件运行相关测试，提升效率。</li><li><strong>优化Draft PR</strong>：默认不触发测试，手动请求时才运行。</li><li><strong>减少不必要的测试</strong>：仅对修改的文档进行跳过<code>make check</code>。</li></ul><h4 id="_3-jenkins-ci系统的优化" tabindex="-1">3. <strong>Jenkins CI系统的优化</strong> <a class="header-anchor" href="#_3-jenkins-ci系统的优化" aria-label="Permalink to &quot;3. **Jenkins CI系统的优化**&quot;">​</a></h4><ul><li><strong>测试失败统计</strong>：改进统计方式，帮助识别需优化的测试。</li><li><strong>测试并行性</strong>：改进并行构建策略，节省资源。</li><li><strong>缓存机制</strong>：引入缓存机制，避免重复构建。</li></ul><h4 id="_4-测试可靠性与优先级" tabindex="-1">4. <strong>测试可靠性与优先级</strong> <a class="header-anchor" href="#_4-测试可靠性与优先级" aria-label="Permalink to &quot;4. **测试可靠性与优先级**&quot;">​</a></h4><ul><li><strong>RBD测试特殊性</strong>：RBD团队希望在Jenkins上尽可能多地运行测试，作为Toothology的前置验证。</li><li><strong>测试优先级</strong>：优先运行与修改代码相关的测试，减少全量测试。</li></ul><h4 id="_5-全局测试与组件测试的权衡" tabindex="-1">5. <strong>全局测试与组件测试的权衡</strong> <a class="header-anchor" href="#_5-全局测试与组件测试的权衡" aria-label="Permalink to &quot;5. **全局测试与组件测试的权衡**&quot;">​</a></h4><ul><li><strong>全局测试价值</strong>：跨组件的依赖问题在全局测试中有用。</li><li><strong>组件测试灵活性</strong>：根据修改的代码自动选择性运行，减少不必要的测试。</li></ul><h3 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h3><ol><li><strong>优化Draft PR</strong>：默认不触发测试，减少Jenkins负载。</li><li><strong>按需触发测试</strong>：仅在PR准备好合并时手动触发全量测试。</li><li><strong>按组件拆分测试</strong>：根据修改的代码自动选择性运行相关测试。</li><li><strong>RBD测试保留</strong>：保留在Jenkins上运行RBD测试，作为Toothology的前置验证。</li></ol><h3 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h3><ol><li><strong>与构建团队沟通</strong>：讨论在Jenkins中实现优化建议。</li><li><strong>改进测试统计</strong>：收集测试失败率和运行时间数据。</li><li><strong>组件测试拆分</strong>：各组件团队决定是否拆分测试。</li><li><strong>缓存机制引入</strong>：探讨在Jenkins中引入缓存机制。</li></ol><h3 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h3><p>本次会议重点讨论了如何改进<code>make check</code>的可靠性和减少运行时间，提出了按需触发测试、按组件拆分测试等建议。同时，会议还探讨了Jenkins CI系统的优化方向，包括缓存机制和测试并行性。各组件团队将根据需求决定测试的拆分和优化策略。</p>',21)])])}const k=o(n,[["render",l]]);export{_ as __pageData,k as default};
